#include "UserManager.h"
#include "App/AppPaths.h"
namespace vox {UserManager::UserManager(){auto dir=AppPaths::data().getChildFile("Admin");dir.createDirectory();usersFile=dir.getChildFile("users.json");if(!usersFile.existsAsFile()){UserAccount owner;owner.id=juce::Uuid().toString();owner.name=juce::SystemStats::getLogonName();owner.windowsIdentity=owner.name;owner.role=Role::SuperAdministrator;owner.status=UserStatus::Active;owner.created=owner.lastAccess=juce::Time::getCurrentTime();save({owner});}}juce::Array<UserAccount>UserManager::users()const{juce::Array<UserAccount>out;auto parsed=juce::JSON::parse(usersFile);if(auto*a=parsed.getArray())for(auto&v:*a)out.add(UserAccount::fromJson(v));return out;}bool UserManager::save(const juce::Array<UserAccount>&items)const{juce::Array<juce::var>data;for(auto&u:items)data.add(u.toJson());juce::TemporaryFile temp(usersFile);return temp.getFile().replaceWithText(juce::JSON::toString(juce::var(data),true))&&temp.overwriteTargetFileWithTemporary();}UserAccount UserManager::currentUser(){auto identity=juce::SystemStats::getLogonName();auto items=users();for(auto&u:items)if(u.windowsIdentity.equalsIgnoreCase(identity)){u.lastAccess=juce::Time::getCurrentTime();upsert(u);return u;}return{};}bool UserManager::upsert(const UserAccount&user){auto items=users();bool found=false;for(auto&u:items)if(u.id==user.id){u=user;found=true;break;}if(!found)items.add(user);return save(items);}bool UserManager::remove(const juce::String&id){auto items=users();for(int i=items.size();--i>=0;)if(items.getReference(i).id==id)items.remove(i);return save(items);}}
